function b({registerIndicator:y,sourceValues:N,nulls:g}){const u=(l,i)=>{const c=2/Math.max(i,1),m=new Array(l.length).fill(NaN);let t=NaN,o=NaN,s=1,h=!0;for(let n=0;n<l.length;n++){const a=l[n];if(Number.isFinite(a))if(!Number.isFinite(t))t=0,o=a;else if(t=c*(a-t)+t,h){s*=1-c;const r=1-s;o=Math.abs(r)>1e-12?t/r:t,s<=1e-10&&(h=!1)}else o=t;m[n]=o}return m};y({id:"oa-ppo",name:"Percentage Price Oscillator (PPO)",category:"Momentum",placement:"pane",inputs:[{key:"source",type:"source",label:"Source",default:"close"},{key:"fastLength",type:"number",label:"Fast Length",default:12,min:1,max:5e3,step:1},{key:"slowLength",type:"number",label:"Slow Length",default:26,min:1,max:5e3,step:1},{key:"signalLength",type:"number",label:"Signal Length",default:9,min:1,max:5e3,step:1}],plots:[{key:"ppo",type:"line",title:"PPO",style:{color:"#2962ff",lineWidth:2}},{key:"signal",type:"line",title:"Signal",style:{color:"#ff5252",lineWidth:2}},{key:"histogram",type:"histogram",title:"Histogram",style:{color:"#787b86"}}],calc(l,i){const c=Math.max(1,Math.floor(Number(i.fastLength)||12)),m=Math.max(1,Math.floor(Number(i.slowLength)||26)),t=Math.max(1,Math.floor(Number(i.signalLength)||9)),o=N(l,i.source??"close"),s=u(o,c),h=u(o,m),n=new Array(l.length).fill(NaN);for(let e=0;e<l.length;e++){const p=s[e],f=h[e];!Number.isFinite(p)||!Number.isFinite(f)||f===0||(n[e]=100*(p-f)/f)}const a=u(n,t),r=new Array(l.length).fill(NaN);for(let e=0;e<l.length;e++)!Number.isFinite(n[e])||!Number.isFinite(a[e])||(r[e]=n[e]-a[e]);return{ppo:g(n),signal:g(a),histogram:g(r)}}})}export{b as default};
